package pt.realmcouncil.network;

import com.google.gson.JsonParser;
import io.netty.buffer.Unpooled;
import net.minecraft.core.RegistryAccess;
import net.minecraft.network.RegistryFriendlyByteBuf;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import java.util.*;
import java.util.regex.Pattern;
import static org.junit.jupiter.api.Assertions.*;

class ResourcesAndPacketsTest {
    private static Map<String,String> lang(String locale)throws Exception {var path=Path.of("src/main/resources/assets/realmcouncil/lang/"+locale+".json");var object=JsonParser.parseString(Files.readString(path)).getAsJsonObject();var map=new HashMap<String,String>();object.entrySet().forEach(e->map.put(e.getKey(),e.getValue().getAsString()));return map;}
    @Test void allLanguagesHaveTheSameKeysAndPlaceholders()throws Exception {var en=lang("en_us");assertEquals(en.keySet(),lang("pt_pt").keySet());assertEquals(en.keySet(),lang("pt_br").keySet());for(var key:en.keySet()){assertEquals(en.get(key).split("%s",-1).length,lang("pt_pt").get(key).split("%s",-1).length,key);assertFalse(en.get(key).isBlank(),key);}}
    @Test void everyGuiLiteralAndDomainErrorHasATranslation()throws Exception {var en=lang("en_us");var pattern=Pattern.compile("\"((?:title|tab|button|label|hint|phase|outcome|symbol|race|time)\\.[a-z_]+)\"");try(var files=Files.walk(Path.of("src/main/java/pt/realmcouncil/client"))){for(var f:files.filter(p->p.toString().endsWith(".java")).toList()){var m=pattern.matcher(Files.readString(f));while(m.find())assertTrue(en.containsKey("gui.realmcouncil."+m.group(1)),m.group(1));}}var errors=Pattern.compile("(?:require\\([^;]+?,|RuleException\\()\\s*\"([a-z_]+)\"");try(var files=Files.walk(Path.of("src/main/java/pt/realmcouncil"))){for(var f:files.filter(p->p.toString().endsWith(".java")).toList()){var m=errors.matcher(Files.readString(f));while(m.find())assertTrue(en.containsKey("error.realmcouncil."+m.group(1)),m.group(1));}}}
    @Test void allThreeBlocksHaveFourDirectionsRecipesLootAndValidTextures()throws Exception {var a=Path.of("src/main/resources/assets/realmcouncil");var d=Path.of("src/main/resources/data/realmcouncil");for(var name:List.of("ballot_box","notice_board","oath_desk")){var states=JsonParser.parseString(Files.readString(a.resolve("blockstates/"+name+".json"))).getAsJsonObject().getAsJsonObject("variants");assertEquals(4,states.size());var model=JsonParser.parseString(Files.readString(a.resolve("models/block/"+name+".json"))).getAsJsonObject();for(var entry:model.getAsJsonObject("textures").entrySet()){String texture=entry.getValue().getAsString();assertTrue(Files.isRegularFile(a.resolve("textures/"+texture.substring(texture.indexOf(':')+1)+".png")),texture);}assertTrue(model.getAsJsonArray("elements").size()>=5);assertTrue(Files.isRegularFile(d.resolve("recipe/"+name+".json")));assertTrue(Files.isRegularFile(d.resolve("loot_table/blocks/"+name+".json")));}}
    @Test void customFontUsesTheMinecraftFontRootAndHasAFallback()throws Exception {var a=Path.of("src/main/resources/assets/realmcouncil");var font=JsonParser.parseString(Files.readString(a.resolve("font/journal.json"))).getAsJsonObject().getAsJsonArray("providers");String file=font.get(0).getAsJsonObject().get("file").getAsString();assertTrue(Files.isRegularFile(a.resolve("font/"+file.substring(file.indexOf(':')+1))));assertTrue(font.asList().stream().anyMatch(v->v.getAsJsonObject().has("id")&&v.getAsJsonObject().get("id").getAsString().equals("minecraft:default")));}
    @Test void optionalModMetadataDoesNotRequireCronicas()throws Exception {String text=Files.readString(Path.of("src/main/templates/META-INF/neoforge.mods.toml"));assertTrue(text.contains("modId=\"cronicasrp\"\ntype=\"optional\""));assertNull(getClass().getResource("/pt/cronicasrp/CronicasRP.class"));}
    @Test void allActionsRoundtripWithNoTrailingBytes(){var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),RegistryAccess.EMPTY);try{for(int action=0;action<=18;action++){var packet=new CouncilPackets.Action(action,UUID.randomUUID().toString(),3,"moon","Um lema válido","Propostas para o reino.");CouncilPackets.Action.CODEC.encode(b,packet);assertEquals(packet,CouncilPackets.Action.CODEC.decode(b));assertEquals(0,b.readableBytes());}}finally{b.release();}}
    @Test void largePublicStateAndMessagesRoundtrip(){var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),RegistryAccess.EMPTY);try{var p=new CouncilPackets.State("x".repeat(150000),true,"error.already_voted");CouncilPackets.State.CODEC.encode(b,p);assertEquals(p,CouncilPackets.State.CODEC.decode(b));assertEquals(0,b.readableBytes());}finally{b.release();}}
    @Test void invalidStationCloseMessageRoundtripsWithoutASnapshot(){var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),RegistryAccess.EMPTY);try{var p=new CouncilPackets.State("",false,"error.station");CouncilPackets.State.CODEC.encode(b,p);assertEquals(p,CouncilPackets.State.CODEC.decode(b));assertEquals(0,b.readableBytes());}finally{b.release();}}
    @Test void oversizedRequestsAndTruncatedPacketsAreRejected(){var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),RegistryAccess.EMPTY);try{assertThrows(RuntimeException.class,()->CouncilPackets.Action.CODEC.encode(b,new CouncilPackets.Action(1,"",1,"sun","x".repeat(81),"")));b.clear();b.writeVarInt(3);assertThrows(RuntimeException.class,()->CouncilPackets.Action.CODEC.decode(b));}finally{b.release();}}
}
